function fibPoints(n) {
  const pts = [];
  const ga = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < n; i++) {
    const y = 1 - (i + 0.5) / n * 2;
    const rr = Math.sqrt(Math.max(0, 1 - y * y));
    const t = ga * i;
    pts.push([Math.cos(t) * rr, y, Math.sin(t) * rr]);
  }
  return pts;
}

